import StateMap 1.0

StateProperty {
	name: "FocusArea"
	translatorType: 4

	readonly property string currentCollection: Planck.getProperty("/Client/Librarian/Collections").translator.string

	readonly property string currentFocusArea: translator ? translator.string : ""
	property string previousFocusArea

	property bool rememberPreviousFocusArea: currentFocusArea.length > 0

	function setFocusAreas(stringList) {
		if(rememberPreviousFocusArea) {
			previousFocusArea = currentFocusArea
		}

		if(Qt.inputMethod.visible ||
		   (PlanckGUI.activeFocusItem && PlanckGUI.activeFocusItem instanceof TextInput)) {
			previousFocusArea = FocusAreaSearchField
		}

		const previousAreas = translator.entries
		const previousAreaIndex = Math.max(0, previousAreas.indexOf(previousFocusArea))
		let focusAreaIndexToSelect = stringList.indexOf(previousFocusArea)

		// Focus exception: Focus Collection->Tracklist instead of
		// Collection->Navigation (default) when Collection is collapsed
		if(previousFocusArea==="Collections" && (focusAreaIndexToSelect < 0))
		{
			focusAreaIndexToSelect = stringList.indexOf("Tracklist")
		}

		const previousAreaStillAvailable = focusAreaIndexToSelect >= 0
		if(!previousAreaStillAvailable) {
			// Find the rightmost common focus area in the new area list:
			for(let i = 0; i < previousAreaIndex; ++i) {
				if(i < stringList.length && i < previousAreas.length && stringList[i] === previousAreas[i]) {
					focusAreaIndexToSelect = i
				}
				else {
					break
				}
			}
		}

		translator.setQStringListWithIndex(stringList, Math.max(0, focusAreaIndexToSelect), 0)
	}
}

