	readonly property string screenGeometryTag: `${PlanckGUI.views.isPortrait ? "_portrait" : PlanckGUI.views.isAspect16x9 ? "_16x9" : ""}`
	splashScreenImageLocation: Qt.resolvedUrl(`../img/SplashScreen${screenGeometryTag}.png`)

	readonly property string currentCollectionCategory: Planck.getProperty("/Client/Librarian/CollectionCategories").translator.string

	readonly property QObjProperty pSelectDatabaseSource: Planck.getProperty("/GUI/SelectDatabaseSource")
	readonly property int numberOfConnectedDevices: Planck.librarianController.devicesController.deviceModelCountObserver.count
	readonly property bool devicesConnected: numberOfConnectedDevices > 0
	onNumberOfConnectedDevicesChanged: {
		if(currentCollectionCategory === CollectionCategoryPlanck &&
			 numberOfConnectedDevices > 0 &&
			 currentDevice.length < 1 &&
			 !pSelectDatabaseSource.translator.state) {
			pSelectDatabaseSource.translator.state = true
		}
	}

	readonly property QObjProperty pCurrentDevice: Planck.getProperty("/Client/Librarian/DevicesController/CurrentDevice")
	readonly property string currentDevice: pCurrentDevice && pCurrentDevice.translator ? pCurrentDevice.translator.string : ""
	readonly property bool failToLoginEaasSource: Planck.librarianController.devicesController.failToLoginEaasSource

	onCurrentDeviceChanged: {
		if(currentCollectionCategory === CollectionCategoryPlanck) {
			if(currentDevice.length > 0) {
				pShowBrowseView.translator.state = true
			}
			else {
				if(!failToLoginEaasSource) {
					if(Config.ui.hasViewsToggle) {
						pShowBrowseView.translator.state = false
					}
					pSelectDatabaseSource.translator.state = true
				}
			}
		}
	}

	Component.onCompleted: {
		Planck.librarianController.devicesController.checkAllDevicesForFirmwareUpdate()
		Planck.librarianController.devicesController.isQmlReadyForDeviceAutoSelection = true

		if(PlanckGUI.views.splashScreenController.viewModel.isUnlocked) {
			Planck.librarianController.devicesController.autoSelectDevice()

			if(numberOfConnectedDevices === 1) {
				var pAskToLoadProfile = Planck.getProperty("/GUI/AskToLoadProfile")
				if (pAskToLoadProfile && pAskToLoadProfile.translator) {
					pAskToLoadProfile.translator.state = true
				}
			}
		}
	}
}

