OverlayContent {
	id: onBoardingProfileLogin

	property bool done: false
	property ProfilesLoginController controller: Planck.librarianController.profilesLoginController
	property bool showCloseButton: false

	function abort() {
		done = true
		controller.selectedView = ProfilesLoginController.Idle
	}

	headerComponent: ProfilesLoginHeader {
		active: !controller.tokenLoaded
		showCloseButton: onBoardingProfileLogin.showCloseButton
	}
	contentComponent: ProfilesLoginContent {
		active: !controller.tokenLoaded
	}

	Component.onCompleted: {
		if(controller.tokenLoaded) {
			done = true
			controller.selectedView = ProfilesLoginController.Idle
		}
		else {
			controller.selectedView = ProfilesLoginController.ProfilesPairing
		}
	}

	states: [
		State {
			name: "showWifi"
			when: controller.selectedView === ProfilesLoginController.WifiSelect
			PropertyChanges { target: onBoardingProfileLogin; showCloseButton: true }
			PropertyChanges { target: onBoardingView; cancelButtonVisible: false }
		},
		State {
			name: "showSuccess"
			when: controller.selectedView === ProfilesLoginController.ProfilesSuccess
			PropertyChanges {
				target: onBoardingView;
				cancelButtonText: "Done"
				cancelButtonColor: Style.active01Color
				cancelButtonTextColor: Style.surface01Color
				showCheckBox: false
			}
		}
	]
}

