SlideDialog {
	id: searchMenuDialog
	objectName: "SearchCriteriaMenu"

	anchors.fill: parent

	property var roles

	property real rowHeight
	property real rowWidth
	property real menuSpacing

	bodyMargins: menuSpacing
	slideFromLeft: true

	property var titleRoleMap: ({})
	property var searchConstraint: ({})

	readonly property QObjProperty pSearchAll: Planck.getProperty("/Client/Librarian/SearchAll")
	readonly property bool searchAll: pSearchAll && pSearchAll.translator ? pSearchAll.translator.state : false

	readonly property bool inBrowseView: Planck.getProperty("/GUI/ShowBrowseView").translator.state
	onInBrowseViewChanged: onScreen = false

	function setConstraint(name, active) {
		if(active) {
			searchConstraint[name] = true
		}
		else {
			delete searchConstraint[name]
		}
		searchConstraintChanged()
	}

	function isConstraintActive(name) {
		return !searchAll && searchConstraint[name] === true
	}

	body: Item {
		id: frame
		width: searchMenuDialog.rowWidth
		height: childrenRect.height + infoBackground.margin + allCell.anchors.topMargin

		UnderlinedButton {
			id: allCell
			objectName: "SearchCriteriaButton"
			anchors.top: frame.top
			anchors.topMargin: menuSpacing
			width: grid.width
			height: rowHeight
			active: searchAll
			text: "Search All"
			onClicked: pSearchAll.translator.state = !searchAll
		}

		Grid {
			id: grid
			anchors.left: parent.left
			anchors.top: allCell.bottom
			anchors.topMargin: menuSpacing
			width: parent.width - menuSpacing

			columns: 2
			spacing: menuSpacing

			Repeater {
				id: buttons
				objectName: "SearchCriteriaRepeater"
				// We could use Object.keys but that sorts them alphabetically.
				model: roles

				UnderlinedButton {
					objectName: "SearchCriteriaButton"
					id: cell
					width: (grid.width - grid.spacing) / 2
					height: rowHeight
					text: titleRoleMap[cell.role] ? titleRoleMap[cell.role] : ''
					active: Boolean(searchConstraint[cell.role]) && !searchAll
					property string role: modelData
					readonly property bool isActive: isConstraintActive(role)

					MouseArea {
						anchors.fill: cell
						acceptedButtons: Qt.LeftButton
						onClicked: {
							if(searchAll) {
								pSearchAll.translator.state = !searchAll
								return
							}

							var numberOfActiveConstraints = Object.keys(searchConstraint).length

							if(cell.isActive) {
								if(numberOfActiveConstraints === 1) {
									pSearchAll.translator.state = true
								}
								else {
									setConstraint(cell.role, false)
								}
							}
							else {
								setConstraint(cell.role, true)
							}
						}
					}
				}
			}
		}

		MouseArea {
			anchors.fill: grid
			acceptedButtons: Qt.LeftButton
			visible: searchAll
			opacity: searchAll ? 1 : 0
			Behavior on opacity { NumberAnimation { duration: 200 } }
			onClicked: pSearchAll.translator.state = !searchAll

			Rectangle {
				anchors.fill: parent
				color: Style.opaqueBase01Color
			}
		}

		Text {
			anchors {
				top: grid.bottom
				topMargin: 15
				left: grid.left
				right: grid.right
				leftMargin: 10
				rightMargin: 10
			}
			wrapMode: Text.WrapAtWordBoundaryOrAnywhere
			horizontalAlignment: Text.AlignHCenter
			text: "To reduce search time, please select only fields in which you wish to search."
			font: hintFont.font
			color: Style.font02Color

			AIRFont {
				id: hintFont
				pointSizeF: 14
				family: root.robotoLightFontLoader.name
			}

			Rectangle {
				id: infoBackground
				z: -1
				readonly property real margin: 10
				anchors {
					fill: parent
					margins: -margin
				}
				color: Style.systemBlue01Color
			}
		}
	}
}

