BreadcrumbView {
	id: craylists
	objectName: "Craylist"
	editMode: songEditMode
	isEditingSource: Planck.getProperty("/Client/Librarian/SongEditCollection").translator.string ===  "Craylist"
	missingContentHint: "No Playlists Found"
	defaultSubIndex: -1
	property bool songEditMode: false
	property var controller: Planck.librarianController.craylistController
	focusArea: FocusAreaCollections
	pControllerCurrentIndex: Planck.getProperty("/Client/Librarian/CraylistController/CurrentIndex")
	pControllerAction: Planck.getProperty("/Client/Librarian/CraylistController/OpenOrCloseCurrentIndex")
	fetchingContent: model ? model.fetchingContent : false
	model: Planck.librarianController.devicesController.selectedDeviceCraylistModel
	rootModelIndex: Planck.librarianController.devicesController.selectedDeviceCraylistRootModelIndex
	title: "Collection"
	path: title
	itemDragKeys: function (modelData) {
		if(modelData.typeRole === ListsModel.Stemslist) {
			return []
		}
		return [TouchDragReorderLists, TouchDragListToList, TouchDragListToStemsList]
	}
	itemDropKeys: function (modelData) {
		if(modelData.typeRole === ListsModel.Stemslist) {
			if(Config.device.hasStemsProEmbeddedRendering) {
				return [TouchDragListToStemsList, TouchDragTracksToStemsList]
			}
			return []
		}
		if(modelData.typeRole === ListsModel.Smartlist) {
			return [TouchDragReorderLists]
		}
		return [TouchDragReorderLists, TouchDragListToList, TouchDragTracksToList]
	}

	onSwipedLeft: controller.removeList(index)

	onSongEditModeChanged: {
		if(visible && !songEditMode) {
			controller.reselectCurrentSelection()
		}
	}

	onCurrentModelIndexChanged: {
		if(enabled && currentModelIndex) {
			if(currentModelIndex.model === model) {
				const updateIndexOnly = editMode && !selectedModelConnection.ignoreEditModeForNextSelect
				controller.select(currentModelIndex, 1, true, updateIndexOnly)

				const tracklistUpdated = editMode && selectedModelConnection.ignoreEditModeForNextSelect
				if(tracklistUpdated) {
					currentTracklistModelIndex = currentModelIndex
					currentTracklistPath = currentListPath
				}

				selectedModelConnection.ignoreEditModeForNextSelect = false
			}
		}
	}

	Connections {
		id: selectedModelConnection
		target: model
		function onRowsAboutToBeRemoved(parent, first, last) {
			const tracklistSourceRemoved = model.index(first, 0, parent) === currentTracklistModelIndex
			ignoreEditModeForNextSelect = editMode && tracklistSourceRemoved
		}

		property bool ignoreEditModeForNextSelect: false
	}

	Connections {
		target: Planck.librarianController.craylistController
		function onTracksAdded(index) {
			if(model === index.model) {
				showAddedHint(index, false)
			}
		}
	}

	footer: Item {
		objectName: "Craylist_Footer"
		height: songEditMode ? createCraylistButton.height : 0
		property alias isAnimationRunning: craylistFooterAnimation.running
		Behavior on height {
			NumberAnimation {
				id: craylistFooterAnimation
				duration: 200
				easing {
					type: Easing.OutBack
					overshoot: 2
				}
			}
		}
		visible: height > 0

		CreateCollectionButton {
			id: createCraylistButton

			anchors.right: parent.right
			anchors.left: parent.left
			collectionType: "Craylist"
			controller: Planck.librarianController.craylistController
		}
	}

	onDropped: {
		if(info.matchingKeys.indexOf(TouchDragTracksToList) > -1) {
			var index = info.targetIndex
			var tracks = [];

			for (var key in info.payload)  {
				var trackInfo = info.payload[key]
				tracks.push(trackInfo.uniqueID)
			}

			controller.addTracksToList(index, tracks);
		}
		else if(info.matchingKeys.indexOf(TouchDragListToList) > -1 || info.matchingKeys.indexOf(TouchDragReorderLists) > -1) {
			var sourcePath = controller.getListPath(info.payload)
			var targetPath = controller.getListPath(info.targetIndex)
			var option
			switch(info.dropType) {
			case AIRTouchEnums.Above:
				option = InsertListOptions.Before
				break;
			case AIRTouchEnums.Below:
				option = InsertListOptions.After
				break;
			case AIRTouchEnums.Inside:
				option = InsertListOptions.Into
				break;
			default:
				if(info.dropType !== AIRTouchEnums.None) {
					console.warn('Incorrect drop type in Playlists.')
				}
				return
			}
			controller.moveList(sourcePath, targetPath, option)
		}
		else if(info.matchingKeys.indexOf(TouchDragListToStemsList) > -1) {
			Planck.librarianController.stemsQueueManager.startRenderTracksFromListPath(controller.getListPath(info.payload), controller.getSourceDevice(info.payload))
			showAddedHint(info.targetIndex, true)
		}
		else if(info.matchingKeys.indexOf(TouchDragTracksToStemsList) > -1) {
			var tracks = []

			for (var key in info.payload)  {
				var trackInfo = info.payload[key]
				tracks.push(trackInfo.uniqueID)
			}
			Planck.librarianController.stemsQueueManager.startRenderTracks(tracks.join(";"))
			showAddedHint(info.targetIndex, true)
		} else {
			console.warn('Unimplemented drop to Playlists.')
		}
	}
}

