BreadcrumbView {
	objectName: "Files"
	missingContentHint: "No Files Found"
	defaultSubIndex: -1
	property bool songEditMode: false
	focusArea: FocusAreaCollections
	pControllerCurrentIndex: Planck.getProperty("/Client/Librarian/FileBrowserController/CurrentIndex")
	pControllerAction: Planck.getProperty("/Client/Librarian/FileBrowserController/OpenOrCloseCurrentIndex")
	title: "Folder"
	path: Planck.getProperty("/Client/Librarian/DevicesController/CurrentDeviceName").translator.string
	initializeWhenVisible: true
	readonly property QObjProperty pCurrentDevice: Planck.getProperty("/Client/Librarian/DevicesController/CurrentDevice")
	readonly property string currentDevice: pCurrentDevice && pCurrentDevice.translator ? pCurrentDevice.translator.string : ""
	onCurrentModelIndexChanged: {
		if(enabled && !songEditMode) {
			if(currentModelIndex) {
				Planck.librarianController.fileBrowserController.selectedFolder = Planck.resolvePath(currentModelIndex.model.data(currentModelIndex, FolderModel.FullPath))
			}
			else {
				Planck.librarianController.fileBrowserController.selectedFolder = currentDevice
			}
		}
	}

	modelComponent: Component {
		HumanizedSortModel {
			id: sortModel
			property var sourceParentIndex
			readonly property bool hasChildren: sourceModel ? !sourceModel.isEmpty : false
			readonly property bool isFetching: sourceModel ? sourceModel.isFetching : false
			property var folderModel: FolderModel { }
			property string rootPath: ""
			sourceModel: {
				folderModel.jobController = Planck.librarianController.jobController
				folderModel.rootPath = Qt.binding(_ => sortModel.rootPath)
				folderModel
			}
		}
	}

	function createModelComponent(p, m, ri) {
		return modelComponent.createObject(p, {"rootPath": Planck.getProperty("/Client/Librarian/DevicesController/CurrentDevice").translator.string})
	}

	function createChildModelComponent(p, m, i) {
		return modelComponent.createObject(p, {"sourceParentIndex": m.index(i, 0), "rootPath": m.data(m.index(i, 0), FolderModel.FullPath)})
	}

	Connections {
		target: Planck.librarianController.fileBrowserController

		function getTestFunc(path) {
			return function() {
				return function(item) {
					return item.model.sourceModel.rootPath === path
				}
			}
		}

		function onRefreshFolderModel(path) {
			var stackItem = findStackItem(getTestFunc(path))

			if(!stackItem) {
				return
			}

			stackItem.model.sourceModel.refresh()
		}

		function onCurrentPathInvalidated(lastValidPath) {
			var stackItem = findStackItem(getTestFunc(lastValidPath))

			if(!stackItem) {
				return
			}

			unwindStack(stackItem)
		}
	}
}

