BreadcrumbView {
	id: filters
	objectName: "Filters"
	missingContentHint: "No Files Found"
	defaultSubIndex: -1
	shouldEnterCurrentItem: true
	focusArea: FocusAreaCollections
	title: "Filters"
	path: title
	fetchingContent: Planck.librarianController.filterBoxController.isWaitingForFilterResult && !responsiveBrowseView.trackListObject.updating
	updatingHintText: "UPDATING"
	property bool filtersApplied: false
	model: ListModel {
		function rebuildModel() {
			filters.filtersApplied = false
			clear();
			append({"id": 0, "display": "Genre", "subModel": Planck.librarianController.filterBoxController.filterBoxModels[0], "subIndex": Planck.librarianController.filterBoxController.filterBoxModels[0].index(-1, -1)})
			append({"id": 1, "display": "Artist", "subModel": Planck.librarianController.filterBoxController.filterBoxModels[1], "subIndex": Planck.librarianController.filterBoxController.filterBoxModels[1].index(-1, -1)})
			append({"id": 2, "display": "Album", "subModel": Planck.librarianController.filterBoxController.filterBoxModels[2], "subIndex": Planck.librarianController.filterBoxController.filterBoxModels[2].index(-1, -1)})
			append({"id": 3, "display": "BPM", "subModel": Planck.librarianController.filterBoxController.filterBoxModels[3], "subIndex": Planck.librarianController.filterBoxController.filterBoxModels[3].index(-1, -1)})
			append({"id": 4, "display": "Key", "subModel": Planck.librarianController.filterBoxController.filterBoxModels[4], "subIndex": Planck.librarianController.filterBoxController.filterBoxModels[4].index(-1, -1)})
		}

		Component.onCompleted: {
			rebuildModel()
		}
	}

	extendRootLevelClickArea: true
	onCurrentModelIndexChanged: {
		if(visible) {
			select()
		}
	}

	function select() {
		if(currentModelIndex) {
			if(currentModelIndex.model) {
				filters.filtersApplied = true
				Planck.librarianController.filterBoxController.selectFilter(currentModelIndex.model.filteringCriteria, currentModelIndex.row);
			} else {
				filters.filtersApplied = false
			}
		}
	}

	readonly property string currentDevice: Planck.getProperty("/Client/Librarian/DevicesController/CurrentDevice").translator.string
	onCurrentDeviceChanged: reset()

	function reset() {
		pop()
		model.rebuildModel()
		invalidate()
	}
}

