	objectName: "BreadcrumbViewHeader"
	property Item breadcrumbView
	property StackView stackView

	width: 100
	height: 80

	property string title
	property alias iconUrl: iconImage.source
	property bool iconAdjustsForDayMode: false

	property bool isSelected: {
		if(breadcrumbView.editMode) {
				stackView.currentItem && breadcrumbView.currentTracklistPath === stackView.currentItem.path && breadcrumbView.isEditingSource
		}
		else {
				stackView.currentItem && stackView.currentItem.currentRowIndex === -1
		}
	}
	property bool isInFocus: breadcrumbView.isCurrentFocusArea
	property bool backButtonVisible: breadcrumbView.canPop
	property bool isFetching: stackView.currentItem ? stackView.currentItem.isFetching : false
	property real spinnerRotation: stackView.spinnerRotation
	property int  bankTag: 0

	property bool enableClick: breadcrumbView.editMode ? breadcrumbView.canPop : breadcrumbView.canSelectHeader

	property bool enableDrop: breadcrumbView.canPop && !stackView.isCurrentItemScrolling

	property color borderColor: "transparent"

	property bool showDropTarget: breadcrumbView.poppable && breadcrumbView.canPop && ((stackView.currentItem && stackView.currentItem.containsDrag) || containsDrag)
	property var parentEntryChildModel

	property alias dropKeys: dropZone.dropKeys
	readonly property bool containsDrag: dropZone.containsDrag

	readonly property bool dropTargetContainsDrag: dropTarget.containsDrag

	property alias headerIsAnimating: background.isAnimating

	signal dropOnTarget(var info)
	anchors {
		left: parent.left
		right: parent.right
	}
	z: 5 // Above the list, but below the drag handler.
	onClicked: {
		if(stackView.busy) {
			return
		}
		breadcrumbView.navigateToUpperLevel()
		if(breadcrumbView.canPop) {
			breadcrumbView.pop()
		}
		else if(stackView.currentItem) {
			stackView.currentItem.currentRowIndex = -1

			const currentDevicePath = Planck.librarianController.devicesController.getCurrentDevicePath()
			const databaseUuid = Planck.librarianController.devicesController.getDatabaseUuid(currentDevicePath)
			rememberLocation.unregisterDatabaseUuid(databaseUuid)
		}
	}
	onDropOnTarget: breadcrumbView.dropped(info)
	parentEntryChildModel: stackView.parentItem ? stackView.parentItem.model : null
	title: stackView.currentItem ? stackView.currentItem.name : ""
	dropKeys: [TouchDragListToList]
	onPressed: {
		if(!enableClick) {
			mouse.accepted = false
		}
		else {
			breadcrumbView.headerPressed()
			forceActiveFocus()
		}
	}

	AIRTouchDropZone {
		id: dropZone
		anchors.fill: parent

		onDragMoved: dropTarget.containsDrag = dropTarget.contains(dropTarget.mapFromItem(dropZone, info.position.x, info.position.y))
		onDragExited: dropTarget.containsDrag = false
		onDrop: {
			if(dropTarget.containsDrag) {
				info.targetIndex = parentEntryChildModel.sourceParentIndex
				info.containsFiles = !!handle.origin.showsFileList // Make a bool from a potential undefined just in case origin is not a BreadcrumbView.
				info.dropType = AIRTouchEnums.Inside
				breadcrumbViewHeader.dropOnTarget(info)
			}

			dropTarget.containsDrag = false
		}
	}

	Rectangle {
		id: background
		anchors.fill: parent
		color: breadcrumbViewHeader.isSelected ? breadcrumbViewHeader.isInFocus ? Style.focus02Color : Style.focus01Color : Style.surface01Color
		property alias isAnimating: headerColorAnimation.running

		border {
			width: 3
			color: borderColor
		}

		Behavior on color { ColorAnimation {
			id: headerColorAnimation
			duration: 150;
			}
		}

		ColoredImage {
			id: backButtonImage
			objectName: "HeaderBackButton"
			x: 24
			anchors.verticalCenter: parent.verticalCenter
			source: Qt.resolvedUrl("img/arrow.png")
			color: breadcrumbViewHeader.isSelected ? Style.icon02Color : Style.icon01Color
			Behavior on color { ColorAnimation { duration: 150; } }

			visible: opacity > 0

			opacity: breadcrumbViewHeader.backButtonVisible ? 1 : 0
			Behavior on opacity { NumberAnimation { duration: 150; } }
		}

		Item {
			id: icon
			width: 59
			height: parent.height
			visible: iconImage.source.toString() !== ""
			anchors.left: backButtonImage.visible ? backButtonImage.right : parent.left
			anchors.leftMargin: backButtonImage.visible ? 5: 0

			Icons.ColoredImage {
				id: iconImage
				anchors.centerIn: icon
				width: icon.width - 10
				height: width
				fillMode: Image.PreserveAspectFit
				color: Style.font01Color
				useOriginal: !breadcrumbViewHeader.iconAdjustsForDayMode
			}
		}

		Item {
			anchors.left: icon.visible ? icon.right : breadcrumbViewHeader.backButtonVisible ? backButtonImage.right : parent.left
			anchors.leftMargin: icon.visible ? 0 : 24
			width: parent.width - x + 10 - (spinner.visible ? spinner.width : 0)
			height: parent.height

			BankTag {
				id: headerBankTag
				index: breadcrumbViewHeader.bankTag

				anchors {
					verticalCenter: parent.verticalCenter
					left: parent.left
					leftMargin: -7
				}

				inFocus: (breadcrumbViewHeader) ? true : false
				width: 32
				visible: (bankTag > 0)
			}

			ScrollableText {
			    objectName: "BreadcrumbViewHeaderScrollable"
				anchors {
					left: (headerBankTag.visible > 0) ? headerBankTag.right : parent.left
					right: parent.right
					rightMargin: 28
					leftMargin: headerBankTag.visible ? 12 : 0
				}
				height: parent.height

				color: Style.font02Color
				scroll: breadcrumbViewHeader.isSelected && breadcrumbViewHeader.isInFocus
				text: breadcrumbViewHeader.title

				font: headerFont.font

				AIRFont {
					id: headerFont
					pointSizeF: 26
					family: root.robotoRegularFontLoader.name
				}
			}
		}

		Spinner {
			id: spinner
			anchors {
				verticalCenter: parent.verticalCenter
				right: parent.right
				rightMargin: 25
			}

			width: 32
			height: 32
			visible: breadcrumbViewHeader.isFetching
			rotation: breadcrumbViewHeader.isFetching ? breadcrumbViewHeader.spinnerRotation : 0
			spinnerAnimation: null
		}

		Row {
			anchors {
				top: parent.top
				right: parent.right
				bottom: parent.bottom
			}
			opacity: showDropTarget && dropKeys.length > 0 ? 1 : 0
			visible: opacity > 0
			Behavior on opacity { NumberAnimation { duration: 200 } }

			LinearGradient {
				height: parent.height
				width: 28
				start: Qt.point(0, 0)
				end: Qt.point(width, 0)
				cached: true
				gradient: Gradient {
					GradientStop { position: 0; color: "transparent" }
					GradientStop { position: 1; color: background.color }
				}
			}

			Rectangle {
				height: parent.height
				width: height
				color: background.color

