Row {
	id: sortRow
	objectName: "Browser_TrackList_SortMenu"

	enabled: !responsiveBrowseView.trackListEmpty 
	readonly property QObjProperty pFocusArea: Planck.getProperty("/Qml/ControlFocus/FocusArea")
