	property SortControllerInterface sortController: PlanckGUI.views.sortController
	property string sortRole: sortController ? sortController.getSortTypeLabel() : "other"
	property int sortOrder: sortController ? (sortController.isAscendingSortOrder() ? Qt.AscendingOrder : Qt.DescendingOrder) : Qt.AscendingOrder

	readonly property RemoteHostScreenServiceInterface service: Planck.librarianController.remoteHostScreenServicesController.currentService
	property bool arrowRotationDisabled: true
	readonly property var titleRoleMap: ({
		song: 'Title',
		bpm: 'BPM',
		artist: 'Artist',
		key: 'Key',
		rating: 'Rating',
		length: 'Length',
		year: 'Year',
