		other: 'Other'
	})

	readonly property bool showButton: true

	property alias dividerColor: divider.color
	property alias dividerHeight: divider.height
	property alias dividerWidth: divider.width

	property var menuRoles: {
		if(showButton) {
			var result = ['song', 'bpm', 'artist', 'key', 'rating', 'length', 'year', 'dateImported', 'genre', 'comment', 'playOrder', 'other']
			return result
		}

