		id: buttonFont
		pointSizeF: 16
		family: root.robotoMediumFontLoader.name
		capitalization: Font.AllUppercase
	}

	Connections {
		target: sortController
		function onSortOrderChangeComanded(sortType, isAscending) {
			if (!isRemoteHostScreen) {
				return
			}

			arrowRotationDisabled = false
			sortRow.sortRole = sortType
			sortRow.sortOrder = isAscending ? Qt.AscendingOrder : Qt.DescendingOrder
		}
	}

	PrimaryButton {
		id: sortMenuButton
		objectName: "Browser_TrackList_SortMenuButton"

		DividerBar {
			id: divider
		}

		iconItem: Sort {}
		iconSize: 48
		implicitHeight: statusBar.height
		implicitWidth: statusBar.height

		backgroundColor: "transparent"
		foregroundColor: pressed ? Style.active01Color : Style.icon02Color

		visible: sortRow.enabled && sortRow.showButton
		onClicked: showMenu(titleRoleMap[sortRole])
	}

	PrimaryButton {
		id: sortOrderButton
		objectName: "Browser_TrackList_SortMenuSortOrderButton"

		DividerBar {
			id: sortMenuDivider
			color: Style.base01Color
			height: divider.height / 2
			width: 2
		}

		iconItem:
			ColoredImage {
				id: sortIcon
				objectName: "SortIcon"

				source: Qt.resolvedUrl("../img/sortArrow.png")
				width: 32
				height: 32

				rotation: sortOrder === Qt.AscendingOrder ? 180 : 0
				property alias sortAnimationRunning: rotationAnimation.running
				Behavior on rotation {
					RotationAnimation {
						id: rotationAnimation
						duration: Style.animationDuration
						direction: RotationAnimation.Clockwise
						easing.type: Easing.OutQuad
					}
				}
			}
		implicitHeight: statusBar.height
		implicitWidth: statusBar.height
		backgroundColor: "transparent"
		foregroundColor: enabled ? (pressed ? Style.active01Color : Style.icon02Color) : Style.disabled01Color

		onClicked: requestToFlipDirection()
	}

	onSortRoleChanged: {
		if (dialog) {
			dialog.sortRole = sortRole
		}
		responsiveBrowseView.sortRole = sortRole
	}

	function showMenu() {
		if (dialog) {
			return
		}

		dialog = root.openDialog(Qt.resolvedUrl("./SortMenuDialog.qml"))
		dialog.hybridMode = true
		dialog.rowHeight = menuRowHeight
		dialog.rowWidth = menuRowWidth
		dialog.menuSpacing = menuSpacing
		dialog.bodyYOffset = menuY
		dialog.sortOrder = sortOrder
		dialog.titleRoleMap = titleRoleMap
		dialog.sortRole = sortRole
		dialog.roles = menuRoles
		dialog.onScreen = true
		dialog.collectionController = sortRow.collectionController

	}

	function requestToFlipDirection() {
		if(!sortController)
		{
			return
		}
		const willBeAscending = (sortOrder === Qt.DescendingOrder)
		sortController.updateSortOrder(sortRow.sortRole || "other", willBeAscending)
		arrowRotationDisabled = true
	}
}

import QtQuick

