AIRTouchListSwipeAction {
	id: swipeAction

	required property bool trackLoadPossible
	required property int rowIndex


	readonly property SwipeActionProviderInterface actionProvider: PlanckGUI.views.swipeActionProvider
	readonly property list<SwipeActionInterface> leftActions: actionProvider.leftActions(row)

	Connections {
		target: actionProvider
		function onActionsChanged() {
			if(!swipeAction.commitAnimating) {
				leftActions = actionProvider.leftActions(row)
			}
		}
	}
	onCommitAnimatingChanged: {
		if(!swipeAction.commitAnimating)
		{
			leftActions = actionProvider.leftActions(row)
		}
	}
	Connections {
		target: row
		function onModelDataChanged() {
			if(!swipeAction.commitAnimating) {
				leftActions = actionProvider.leftActions(row)
			}
		}
	}

	readonly property list<string> actionLabels: leftActions.map( action => action.display.label )
	readonly property list<string> actionCommitMessages: leftActions.map( action => action.display.commitMessage )
	readonly property list<color> actionColors: leftActions.map( action => action.display.color )
	readonly property string primaryActionBlockMessages: leftActions.length && leftActions[0].display.blockMessage || ""

	enabled: leftActions.length > 0 && trackLoadPossible

	actionColor: Style.active02Color
	warningColor: Style.systemBlue01Color
	commitHintColor: Style.fontStaticBrightColor
	buttonColors: actionColors.map(color => Qt.darker(color, 1.2))
	buttonPressedColors: actionColors
	textFont: Style.fontH1
	textColor: Style.fontStaticBrightColor

	textSwipeValid: actionLabels
	textSwipeInvalid: (readyToCommit && primaryActionBlockMessages) || ""
	swipePermitted: !textSwipeInvalid.length

	// handle message from direct load (e.g. using the "Load Left" HW button)
	Connections {
		target: Planck.librarianController.trackLoadArbitrator
		enabled: row.isSelectedRow && trackList.visible
		function onLoadActionResult(accepted, message) {
			if(accepted) {
				textCommitValid = message
			} else {
				textCommitInvalid = message
			}
			directAction(accepted)
		}
	}

	Connections {
		target: Planck.librarianController.preparelistController
		enabled: row.isSelectedRow && trackList.visible
		function onTrackAddedToPrepareList() {
			textCommitValid = "Added to Prepare List"
			directAction(true)
		}
	}

	onCommit: (actionIndex, viaButton) => {
				  textCommitValid = actionCommitMessages[actionIndex]
				  leftActions[actionIndex].trigger(row.index)
				  swipedLeft(row.index, actionIndex, viaButton)
			  }
}

