	Layout.preferredHeight: statusBar.height
	color: "transparent"

	property var headerListName: ""

	readonly property bool showExtendedTrackList: PlanckGUI.views.browseViewController.showExtendedTrackList
	readonly property QObjProperty pCollections: Planck.getProperty("/Client/Librarian/Collections")
	readonly property string currentCollection: pCollections && pCollections.translator ? pCollections.translator.string : ""
	onCurrentCollectionChanged: updateListName()
	onVisibleChanged: updateListName()

	property var bankTag: 0
	property bool showFolderNameInFolderView: false
	property font customFont: Style.fontH0

	property url iconSource: ""
	property bool iconAdjustsForDayMode: false

	Connections {
		target: PlanckGUI.views.browseViewController
		function onShowExtendedTrackListChanged() { updateListName() }
	}

	Connections {
		target: Planck.librarianController.playlistBankController
		function onBankChanged() { updateListName() }
	}

	Connections {
		target: PlanckGUI.views.remoteHostScreenLibraryView
		function onPlaylistCurrentTitleChanged() { updateListName() }
	}

	function updateListName() {
		switch(currentCollection) {
			case CollectionNameCraylist:
				headerListName = Planck.librarianController.craylistController.lastSelectedListName
				bankTag        = Planck.librarianController.craylistController.lastSelectedBankTag
				break;

			case CollectionNameHistory:
				headerListName = Planck.librarianController.historylistsController.selectedTitle
				bankTag        = Planck.librarianController.historylistsController.lastSelectedBankTag
				break;

			case CollectionNameStreamingPlaylists:
				headerListName = Planck.librarianController.streamingPlaylistsController.lastSelectedListName
				bankTag = 0 // AIRDJ-40021: TODO
				break;

			case CollectionNamePreparelist:
				headerListName = "Prepare"
				bankTag        = Planck.librarianController.preparelistController.lastSelectedBankTag
				break;

			case CollectionNameFiles:
				if(showFolderNameInFolderView) {
					headerListName = Planck.librarianController.fileBrowserController.selectedFolderName
					break;
				}

			case CollectionNameRemoteHostScreenPlaylists:
				if(PlanckGUI.views.remoteHostScreenLibraryView) {
					headerListName = PlanckGUI.views.remoteHostScreenLibraryView.playlistCurrentTitle
					bankTag = 0
				}
				break;

			default:
				headerListName = ""
				bankTag = 0
				break;
		}
	}

	RowLayout {
		visible: listName.showExtendedTrackList
		anchors.fill: parent
		spacing: 0

