			ColoredImage {
				id: listIconImage
				anchors.centerIn: listIcon
				width: listIcon.width - 10
				height: width
				fillMode: Image.PreserveAspectFit
				source: iconSource
				color: Style.font01Color
				useOriginal: !iconAdjustsForDayMode
			}
		}

		Item {
			id: listNameTag
			Layout.leftMargin: (PlanckGUI.views.isPortrait) ? 21 : 24
			Layout.alignment: Qt.AlignVCenter
			Layout.preferredWidth: 32
			visible: bankTag > 0

			BankTag {
				index: listName.bankTag
				inFocus: true
				anchors {
					verticalCenter: parent.verticalCenter
					left: parent.left
					leftMargin: 12
				}
			}

			AIRMouseEventBlocker { }
		}

		Text {
			text: headerListName
			elide: Text.ElideRight

			color: Style.font02Color
			font: listName.customFont
			Layout.fillWidth: true
			Layout.alignment: Qt.AlignVCenter
			readonly property var headerListNameLeftMargin: PlanckGUI.views.isPortrait ? 8 : 12
			Layout.leftMargin: listIcon.visible ? 0 : (listNameTag.visible ? headerListNameLeftMargin : 24)

