	property CloudServiceProvider provider: Planck.librarianController.streamingCloudController.getCloudServiceProviderPtr(providerName)
	headline: provider ? provider.displayName : ""
	info: "Select storage device"
	infoVisible: true

	readonly property StreamingInterfaceController controller: Planck.librarianController.streamingInterfaceController

	contentComponent: Item {
		Connections {
			target: cloudStorageSelect
			function onShownChanged() {
				if(cloudStorageSelectDialog.shown) {
					var indexToSelect = 0
					for(var row = 0; row < listView.model.rowCount(); ++row) {
						if(listView.model.data(listView.model.index(row, 0), DeviceModelRoles.Path) === listView.currentDevice) {
							indexToSelect = row
							break;
						}
					}
					listView.currentIndex = indexToSelect
					listView.forceActiveFocus()
				}
				else {
					controller.restorePreviouslySelectedSource()
				}
			}
		}

		Binding {
			target: cloudStorageSelect
			property: "info"
			value: listView.count == 0 ? "Insert media source" : "Select storage device"
			restoreMode: Binding.RestoreBinding
		}

		DeviceList {
			id: listView
			anchors {
				top: parent.top
				left: parent.left
				right: parent.right
				bottom: parent.bottom
				bottomMargin: 0
			}

			interactive: cloudStorageSelectDialog.shown
			model: Planck.librarianController.devicesController.writeableHardwareDeviceModel

			pSelectionIndex: Planck.getProperty("/Client/Librarian/DevicesController/DeviceStorageSelectionIndex")

			readonly property QObjProperty pSelectStorageDevice: Planck.getProperty("/Client/Librarian/DevicesController/SelectStorageDevice")
			readonly property QObjProperty pIsSelectingDevice: Planck.getProperty("/Client/Librarian/DevicesController/IsSelectingDevice")
			readonly property QObjProperty pRootDrive: provider ? Planck.getProperty("/Client/Librarian/CloudServiceProviders/%1/DriveRoot".arg(provider.name)) : null

			property Item itemBeingSelected

			property AIRFont driveStatusFont: AIRFont {
				pointSizeF: 18
				family: root.robotoRegularFontLoader.name
			}

			QmlPropertyFilter {
				id: selectDeviceFilter
				filterProperty: listView.pSelectStorageDevice

				function isActive() {
					return !listView.model.data(listView.model.index(listView.currentIndex, 0), DeviceModelRoles.IsMigrated)
				}
			}

			Connections {
				target: listView.pIsSelectingDevice.translator
				function onStateChanged() {
					if(listView.pIsSelectingDevice.translator.state) {
						listView.itemBeingSelected = listView.currentItem
					}
					else {
						listView.itemBeingSelected = null
						if(listView.currentDevice) {
							cloudStorageSelectDialog.hide()
						}
					}
				}
			}

			Keys.onEnterPressed: pSelectStorageDevice.translator.state = true
			Keys.onReturnPressed: pSelectStorageDevice.translator.state = true

			delegate: DeviceListEntry {
				id: entry

				isStorage: listView.pRootDrive && path === listView.pRootDrive.translator.string

				property bool isBeingSelected: false
				height: 112

				foregroundColor: isStorage ? Style.disabled02Color : Style.icon02Color
				showPlayerNumber: Config.device.isPlayer
				spinnerVisible: entry.isBeingSelected || isMigrating !== undefined && isMigrating

				property real failure: 0
				property bool failed: false

				onPressed: forceActiveFocus()
				onClicked: {
					listView.setSelectionIndex(index)
					listView.pSelectStorageDevice.translator.state = true
				}

				Connections {
					target:listView.pIsSelectingDevice.translator
					function onStateChanged() {
						if(!isMountable && entry.ListView.isCurrentItem) {
							failAnim.start()
							listView.itemBeingSelected = null
						}
					}
				}

				Connections {
					target: listView.pSelectStorageDevice.translator
					function onStateRejected() {
						if(entry.ListView.isCurrentItem) {
							failAnim.start()
						}
					}
				}

				readonly property Component driveStatus: Text {
					id: driveStatus
					anchors {
						verticalCenter: parent.verticalCenter
					}
					font: listView.driveStatusFont.font
					text: {
						if(isCorrupted) {
							"Corrupted Database"
						}
						else if(isIncompatible) {
							"Incompatible Database"
						}
						else if(!isMigrated) {
							if(migrationProgress < 0) {
								"Checking Device"
							}
							else {
								"Please wait until database is upgraded (%1%)".arg(migrationProgress)
							}
						}
						else {
							"UNAVAILABLE"
						}
					}

					color: entry.foregroundColor
					Behavior on color { ColorAnimation { duration: 205 } }
					visible: !isMountable || !isMigrated || isCorrupted || isIncompatible
				}

				accessories: [driveStatus, recordingDestination, mediaSource, mediaStorage, playerNumber]

				backgroundColor: {
					if(entry.failed) {
						Style.error01Color
					}
					else if(isStorage) {
						if(readOnly || isIncompatible) {
							Style.error01Color
						}
						else {
							Style.active01Color
						}
				}
					else if(ListView.isCurrentItem) {
						Style.surface04Color
					}
					else {
						Style.surface02Color
					}
				}

				SequentialAnimation {
					id: failAnim

					PropertyAction {
						target: entry
						property: "failed"
						value: true
					}

					PauseAnimation {
						duration: 500
					}

					PropertyAction {
						target: entry
						property: "failed"
						value: false
					}
				}
			}
		}

		ScrollBar {
			delegate: listView
			anchors.rightMargin: -14
		}
	}
}

