import QtQuick 2.15
import Planck 1.0

Item {
	Connections {
		target: Planck.librarianController.wifiController
		enabled: target.isWifiEnabled
		function onLoginFailed(reason) {
			if(reason === "Operation aborted") { // User hit cancel button, ignoring
				return
			}

			let message = (() => {
				if(reason === "connect-failed") {
					return "Failed to connect to Wi-Fi network."
				}
				else if(reason === "invalid-key") {
					return "Password was not accepted."
				}
				else if(reason === "lost-connection") {
					return "Lost connection to Wi-Fi network."
				}

				return reason
			})()
			let messageObject = {
				id: "WifiLoginFailed",
				title: "Wi-Fi Login Error",
				message: message,
				options: Prompt.Ok,
			}
			PlanckGUI.views.prompts.post(messageObject)
		}
	}
}

