Item {
	id: qr

	readonly property var controller: Planck.librarianController.profilesLoginController
	property string pairingState: "searchingForInternet"
	property string activationLink: ""
	property string userCode: ""
	property string qrCode: ""
	property int timeLeft: -1
	property bool bland: false

	signal loggedIn()

	Connections {
		target: qr.controller
		ignoreUnknownSignals: !enabled
		function onLoginFailed() {
			qr.pairingState = "noInternet"
		}
		function onDeviceIsOffline() {
			qr.pairingState = "noInternet"
		}
		function onLoginSuccessful() {
			loggedIn()
		}
		function onUpdatePairingInfo(verificationURI, userCode, lifeTimeInSeconds, qrCodeString) {
			const mid = userCode.length / 2
			if (mid >= 3) {
				qr.userCode = [userCode.slice(0, mid), ' ', userCode.slice(mid)].join('')
			}
			qr.activationLink = verificationURI
			qr.timeLeft = -1
			qr.timeLeft = lifeTimeInSeconds
			qr.qrCode = qrCodeString
			qr.pairingState = "pairing"
		}
	}

	states: [
		State {
			name: "searchingForInternet"
			when: qr.pairingState === "searchingForInternet"
			PropertyChanges { target: infoPanel; source: Qt.resolvedUrl("SearchingPanel.qml"); active: true }
		},
		State {
			name: "noInternet"
			when: qr.pairingState === "noInternet"
			PropertyChanges { target: infoPanel; source: Qt.resolvedUrl("NoInternetPanel.qml"); active: true }
		},
		State {
			name: "pairing"
			when: qr.pairingState === "pairing"
			PropertyChanges { target: infoPanel; active: false }
		}
	]

	Loader {
		id: infoPanel
		objectName: "infoPanel"
		active: false
		anchors {
			left: parent.left
			right: parent.right
		}
	}

	Loader {
		id: qrPanel
		objectName: "qrPanel"
		active: !infoPanel.active
		anchors.fill: parent
		source: Qt.resolvedUrl("PairingInfoPanel.qml")
		Binding { target: qrPanel.item; property: "timeLeft"; value: qr.timeLeft }
		Binding { target: qrPanel.item; property: "activationLink"; value: qr.activationLink }
		Binding { target: qrPanel.item; property: "userCode"; value: qr.userCode }
		Binding { target: qrPanel.item; property: "qrCode"; value: qr.qrCode }
		Binding { target: qrPanel.item; property: "bland"; value: qr.bland }
	}
}

