						placeholderColor: Style.font01Color
						selectionColor: Style.icon01Color
						selectedTextColor: Style.fontInverted02Color
						cursorColor: Style.active01Color
						KeyNavigation.tab: loginButton.enabled ? loginButton : null
						KeyNavigation.backtab: usernameField
					}
				}

				Row {
					anchors {
						horizontalCenter: parent.horizontalCenter
						horizontalCenterOffset: spinner.visible ? spinner.width / 2 : 0
					}

					AIRButton {
						id: loginButton
						objectName: "LoginButton"
						width: 500
						height: 80
						enabled: !usernameField.empty && !passwordField.empty && !spinner.running
						onClicked: login()
						Keys.onEnterPressed: login()
						Keys.onReturnPressed: login()
						KeyNavigation.backtab: passwordField

						function login() {
							spinner.running = true

							// unlikely it is not possible to register an enum without Qt's macromania.
							const origin = 1; // Streaming::EventOrigin::User

							loginDialog.provider.loginToService(
							      JSON.stringify({
							          'provider': loginDialog.provider.name,
							          'username': usernameField.text,
							          'password': passwordField.text
							      }), origin, "userInterfaceLogin")
						}

						Rectangle {
							anchors.fill: parent
							color: {
								if(parent.enabled) {
									parent.pressed ? Style.active02Color : Style.active01Color
								}
								else {
									Style.fontInverted02Color
								}
							}
							Behavior on color { ColorAnimation { duration: 205 } }
							radius: height / 2
						}

						Text {
							anchors.centerIn: parent
							text: "LOG IN"
							color: {
								if(parent.enabled) {
									parent.pressed ? Style.font02Color : Style.fontInverted02Color
								}
								else {
									Style.disabled01Color
								}
							}
							Behavior on color { ColorAnimation { duration: 205 } }
							font: loginFont.font

							AIRFont {
								id: loginFont
								family: root.robotoMediumFontLoader.name
								pointSizeF: 20
							}
						}
					}

					Spinner {
						id: spinner
						anchors.verticalCenter: parent.verticalCenter
						width: 40
						height: 40
						visible: opacity > 0
						opacity: running ? 1 : 0
