Loader {
	sourceComponent: Row {
		readonly property bool enableMultiSession: false

		spacing: parent.parent.spacing

		Item {
			id: profilesApi

			property var logout: () => { Planck.librarianController.profilesLoginController.logout() }
			property var login: () => { Planck.librarianController.profilesLoginController.showLoginDialog() }

			Connections {
				target: Planck.librarianController.profilesLoginController ?? null
				ignoreUnknownSignals: !enabled

				function onLoginSuccessful() {
					handleLoginSuccessful()
				}

				function onProfileNameRetrievedFromServer(profileName) {
					handleProfileNameRetrievedFromServer(profileName)
				}

				function onProfileImageSourceRetrievedFromServer(profileImageSource) {
					handleProfileImageSourceRetrievedFromServer(profileImageSource)
				}

				function onLoggedOut() {
					handleLoggedOut()
				}
			}
		}

		function displaySignOutDialog(sessionObject) {
			let messageObject = {
				id: "DisplaySignOut" + sessionObject.objectName,
				type: Prompt.Warning,
				message: "Are you sure you want to log out of your Engine DJ Profile?",
				options: Prompt.No | Prompt.Yes,
			}

			let prompt = PlanckGUI.views.prompts.post(messageObject)
			prompt.finished.connect((role) => {
				if(role === Prompt.AcceptRole) {
					profilesApi.logout()
					if(sessionObject) {
						sessionObject.visible = false
					}
				}
			})
		}

		function displayLoginWarningDialog() {
			let messageObject = {
				id: "DisplayLoginWarning",
				type: Prompt.Warning,
				message:
					"Log in to your Engine DJ Profile to automatically connect associated streaming and cloud services.
					<br><br>Existing streaming and cloud service logins will be removed and tracks loaded to deck will be ejected.
					<br><br>To manage your connected services, visit<br>enginedj.com/account.",
				options: Prompt.Cancel | Prompt.Ok,
			}
			let prompt = PlanckGUI.views.prompts.post(messageObject)
			prompt.finished.connect((role) => {
				if(role === Prompt.AcceptRole) {
					profilesApi.login()
				}
			})
		}

		function handleLoginSuccessful() {
			if(session1.visible && session2.visible) return

			if(!session1.visible) {
				session1.reset()
				session1.visible = true
				return
			}

			if(!enableMultiSession) {
				return
			}

			if(!session2.visible) {
				session2.visible = true
				return
			}
		}

		function handleProfileNameRetrievedFromServer(profileName) {
			session1.text = profileName
		}

		function handleProfileImageSourceRetrievedFromServer(profileImageSource) {
			session1.imageSource = profileImageSource
		}

		function handleLoggedOut() {
			session1.visible = false
			session1.reset()
		}

		component LoginIndicator: IdCard {
			objectName: "ProfilesLoginButton"
			font: Style.fontH3
			elide: Text.ElideRight
			color: Style.font02Color
			text: "Log In"
			textFontSize: 18
		}

		LoginIndicator {
			id: loginButton

			imageVisible: false
			textVisible: true
			dividerVisible: false
			contextVisible: false
			visible: enableMultiSession ? !(session1.visible && session2.visible) : !session1.visible

			text: "Log In"
			color: Style.surface01Color
			backgroundColor: Style.active01Color
			borderColor: Style.active01Color

			onTapped: {
				if(Planck.librarianController.streamingInterfaceController.hasLoggedInAccountsWithSSOSupport()) {
					displayLoginWarningDialog()
				}
				else {
					profilesApi.login()
				}
			}
		}

		LoginIndicator {
			id: session1
			text: "Fetching..."
			onContextButtonTapped: displaySignOutDialog(session1)
			visible: Planck.librarianController.profilesLoginController.tokenLoaded
			source: Qt.resolvedUrl("img/default_avatar.png")

			function reset() {
				text = "Fetching..."
				imageSource = ""
			}
		}

		LoginIndicator {
			id: session2
			text: "Jimmy Jones"
			onContextButtonTapped: displaySignOutDialog(session2)
			visible: false
			source: ""

			function reset() {
				text = "Fetching..."
				source = ""
			}
		}
	}
}

