import QtQuick 2.15
import Planck 1.0

Item {
	Connections {
		target: Planck.librarianController.rekordBoxImportJobController
		function onRequestChanged(devicePath) {
			let wasRekordBoxDatabaseImportedBefore = Planck.librarianController.rekordBoxImportJobController.wasRekordBoxDatabaseImportedBefore(devicePath)
			let actionToPerform = wasRekordBoxDatabaseImportedBefore ? "update" : "import"
			let importExtraMessage = wasRekordBoxDatabaseImportedBefore ? "" : "<br><br>Without import, rekordbox tracks can be found in the Contents folder from the Folder Tab."
			let messageObject = {
				id: "RecordBoxImport",
				type: Prompt.Info,
				message: `Would you like to ${actionToPerform} the Rekordbox library from<br> \
				'${Planck.librarianController.deviceName(devicePath)}'?<br><br> \
				The device will be unavailable and the ${actionToPerform} could take some time. \
				Existing playlist and track metadata will be overwritten. \
				${importExtraMessage}`,
				options: [
					{text: "Ignore", role: Prompt.RejectRole},
					{text: "Import", role: Prompt.AcceptRole},
				]
			}
			let prompt = PlanckGUI.views.prompts.post(messageObject)
			prompt.finished.connect((role) => {
				switch(role) {
				case Prompt.AcceptRole:
					Planck.librarianController.rekordBoxImportJobController.start(devicePath)
					break
				case Prompt.RejectRole:
					Planck.librarianController.allowDeviceForNfs(devicePath)
					Planck.librarianController.devicesController.triggerDeviceAutoSelection()
					break
				}
			})
			Planck.librarianController.devicesController.deviceRemoved.connect((path, databaseUuid) => {
				if(path === devicePath) {
					PlanckGUI.views.prompts.drop(messageObject.id)
				}
			})
			Planck.librarianController.blockDeviceForNfs(devicePath)
		}
	}

	Binding {
		target: Planck.librarianController.rekordBoxImportJobController
		when: PlanckGUI.views.storageMode.overlayVisible
		property: "queueNotifications"
		value: true
	}

	Component.onCompleted: Planck.librarianController.rekordBoxImportJobController.queueNotifications = false
}

