// BLocks the user interaction and ejects all devices when created. Destroys
// itself if an ejection fails without firing `completed()`.
Rectangle {
	id: overlay

	anchors.fill: parent
	color: Style.opaqueBase01Color

	opacity: 0
	Behavior on opacity { NumberAnimation { duration: 200 } }

	signal completed()
	signal failed()

	Connections {
		target: Planck.librarianController.devicesController
		function onAllEjected() { completed() }
	}

	readonly property QObjProperty pEjectionFailed: Planck.getProperty("/Client/Librarian/DevicesController/EjectionFailed")
	Connections {
		target: pEjectionFailed.translator
		function onStateChanged() {
			if(pEjectionFailed.translator.state) {
				failed()
				overlay.destroy(0)
			}
		}
	}

	Spinner {
		anchors.centerIn: parent
		width: 100
		height: 100
		running: overlay.visible
	}

	AIRMouseEventBlocker {}

	Timer {
		// Ensures that we don't receive the allEjected while still handling
		// onCompleted to prevent potential destruction before completion.
		id: ejectDelay
		interval: 5
		repeat: false
		onTriggered: {
			overlay.opacity = 1
			Planck.librarianController.devicesController.ejectAllDevices()
		}
	}

	Component.onCompleted: {
		ejectDelay.start()
	}
}

