			property var supportedFileTypes: pSupportedFileTypes && pSupportedFileTypes.translator ? pSupportedFileTypes.translator.entries : ""

			property alias highlightShown: borderHighlightRectangle.visible
			property bool highlight: false

			Text {
				anchors.centerIn: parent
				anchors.verticalCenterOffset: 40
				color: Style.font02Color
				text: "Drop Audio Here"
				textFormat: Text.PlainText

				property QObjProperty pSongLoaded: Planck.getProperty("/Engine/Deck%1/Track/SongLoaded".arg(index + 1))
				property bool songLoaded: pSongLoaded && pSongLoaded.translator ? pSongLoaded.translator.state : false

				property QObjProperty pSongLoading: Planck.getProperty("/Engine/Deck%1/Track/SongLoading".arg(index + 1))
				property bool songLoading: pSongLoading && pSongLoading.translator ? pSongLoading.translator.state : false

				visible: !songLoaded && !songLoading
			}

			Rectangle {
				id: borderHighlightRectangle
				anchors.fill: parent
				visible: parent.highlight
				color: Style.active01Color //todo was transpearant is this a good fit
			}

			onDragEnter: {
				event.dropAction = Qt.CopyAction

				var mimeData = event.mimeData.toVariant()

				if(MimeTypeSystemUriList in mimeData) {
					var urls = mimeData[MimeTypeSystemUriList]
					if(urls.length === 1 && !isDirectory(urls[0])) {
						event.accepted = containsFileTypes(urls, supportedFileTypes)
					}
				}

				highlight = event.accepted
			}

			onDragLeave: highlight = false
			onDrop: {
				highlight = false
				var mimeData = event.mimeData.toVariant()

				if(MimeTypeSystemUriList in mimeData) {
					if(mimeData[MimeTypeSystemUriList].length === 1) {
						event.accepted = true
						Planck.getProperty("/Client/Librarian/AddToDatabaseAndLoadToDeck%1".arg(parent.parent.deckIndex)).translator.url = mimeData[MimeTypeSystemUriList][0]
					}
				}
			}
		}
	}
}

