import QtQuick 2.12
import QtQuick.Layouts 1.12
import QtQuick.Controls 2.12
import EngineOS.UI.Style 1.0

Rectangle {
	id: root
	color: Style.surface01Color

	Connections {
		target: SoundSwitch
		function onBackendStatusChanged(status) {
			backendStatus = status
			backendOnline = (status === SoundSwitchView.BackendStatus.Started)
			if (backendStatus === SoundSwitchView.BackendStatus.Started) {
				mainUI.hideAllPrompt()
				switchPageTo(SoundSwitchView.ScreenPage.MainUI)
			}
		}

		function onShowErrorMessage(errorMsg, cancellable) {
			message.msg = errorMsg
			message.cancellable = cancellable
			switchPageTo(SoundSwitchView.ScreenPage.Message)
		}
	}

	StackLayout {
		id: rootStack

		anchors.fill: parent

		currentIndex: 1

		// 0: wait animation
		WaitAnimation { id: waitAnimation }
		// 1: Select source
		SelectSection { selectSectionType: SourceSection.Type.DataSource }
		// 2: Select project
		SelectSection { selectSectionType: SourceSection.Type.Project }
		// 3: Select Venue
		SelectSection { selectSectionType: SourceSection.Type.Venue }
		// 4: main UI
		MainUI {
			id: mainUI
			onHideView: root.hideView()
		}
		// 5: message
		Message { id: message }
	}

	// should align with these in SoundSwitch.h
	enum BackendStatus { Stopped, Started, AboutToStop, AboutToStart, AboutToRestart }
	// Also see WaitAnimation.qml
	enum ScreenPage { Animation, SourceSelect, ProjectSelect, VenueSelect, MainUI, Message }

	function isOnPage(page) {
		switch (page) {
			case SoundSwitchView.ScreenPage.Animation: {
				return rootStack.currentIndex === 0
			}
			case SoundSwitchView.ScreenPage.SourceSelect: {
				return rootStack.currentIndex === 1
			}
			case SoundSwitchView.ScreenPage.ProjectSelect: {
				return rootStack.currentIndex === 2
			}
			case SoundSwitchView.ScreenPage.VenueSelect: {
				return rootStack.currentIndex === 3
			}
			case SoundSwitchView.ScreenPage.MainUI: {
				return rootStack.currentIndex === 4
			}
			case SoundSwitchView.ScreenPage.Message: {
				return rootStack.currentIndex === 5
			}
			default: {
				return false
			}
		}
	}
	function switchPageTo(page, cancellable) {
		if (page === SoundSwitchView.ScreenPage.Animation) {
			rootStack.currentIndex = 0
			return
		}

		let ni = -1
		switch (page) {
			case SoundSwitchView.ScreenPage.SourceSelect: {
				ni = 1
				break
			}
			case SoundSwitchView.ScreenPage.ProjectSelect: {
				ni = 2
				break
			}
			case SoundSwitchView.ScreenPage.VenueSelect: {
				ni = 3
				break
			}
			case SoundSwitchView.ScreenPage.MainUI: {
				ni = 4
				mainUIReached = true
				mainUI.hideMainMenu()
				break
			}
			case SoundSwitchView.ScreenPage.Message: {
				ni = 5
				break
			}
			default:
				break
		}

		rootStack.currentIndex = ni
	}

	function darker(c) {
		let cd = Qt.darker(c)
		return cd ? cd : "transparent"
	}

	property var preferenceModel: SoundSwitch.preferenceModel()

	property bool mainUIReached: false
	property bool userStarted: false

	readonly property bool isPortraitMode: PlanckGUI.views.isPortrait

	readonly property int spacingValue: 15
	readonly property real mainTabHeight: 70
	readonly property int tabButtonHeight: root.isPortraitMode ? 64 : 56
	readonly property real standardHeight: 800
	readonly property real scaleRate: height / standardHeight

	property int backendStatus: 0
	property bool backendOnline: false

	readonly property bool releaseBuild: SoundSwitch.isReleaseBuild()

	readonly property int numberOfConnectedDevices: Planck.librarianController.devicesController.deviceModelCountObserver.count
	onNumberOfConnectedDevicesChanged: {
		if (userStarted && (isOnPage(SoundSwitchView.ScreenPage.SourceSelect)
		                    || isOnPage(SoundSwitchView.ScreenPage.MainUI))) {
			SoundSwitch.connectedDevicesChanged()
		}
	}

	signal hideView()

	onVisibleChanged: {
		SoundSwitch.ssViewVisible(visible)
		if (!visible) {
			mainUI.hideMainMenu()
		}
		if (visible && !userStarted) {
			userStarted = true
			switchPageTo(SoundSwitchView.ScreenPage.SourceSelect)
			SoundSwitch.guideStart()
		}
	}
}

