Item {
	id: module
	objectName: 'Browse Encoder Module ${module.name}'.trim()

	property int pushNote
	property int turnCC

	property int doubleTapAction: Action.None
	property int ledType: LedType.None
	property bool unloadTrackViaShiftBrowseEncoder: false
	property bool encoderPressed: false
	property bool enableBeatGridEditTurnAssignment: true
	readonly property bool playerCueEditActive: hasDeckConfig && (deckConfig.songLoading || deckConfig.cueEditActive)
	readonly property bool playerGridEditActive: hasDeckConfig && deckConfig.gridEditActive


	readonly property bool hasDeckConfig: typeof deckConfig !== 'undefined'
	readonly property int midiChannel: hasDeckConfig ? deckConfig.midiChannel : globalConfig.midiChannel
	readonly property string name: hasDeckConfig ? deckConfig.name : ''
	readonly property bool hasInstantDouble: doubleTapAction === Action.InstantDouble
	readonly property string unloadTrackPath: hasDeckConfig && deckConfig.inComputerMode
		? `/Engine/RemoteHostScreen/Deck${deckConfig.activeDeckIndex}/TryUnload`
		: `/Engine/Deck${deckConfig.activeDeckIndex}/TryUnload`
	readonly property string shiftActionPath: unloadTrackViaShiftBrowseEncoder ? unloadTrackPath : `/Qml/ControlFocus/ShiftAction`

	readonly property string pushPropertyPath: {
		if(module.hasDeckConfig
				&& (deckConfig.controllerConnected || deckConfig.forceLoadToDeck)
				&& globalConfig.trackSelectedInBrowseView
				&& !globalConfig.shift) {
			`/Client/Librarian/LoadToDeck${deckConfig.activeDeckIndex}`
		}
		else {
			globalConfig.shift ? module.shiftActionPath : `/Qml/ControlFocus/Action`
		}
	}

	ValueNoteAssignment {
		objectName: 'Browse Encoder Local ${module.name}'.trim()
		channel: module.midiChannel
		note: module.pushNote
		output: ActionOutput {
			behaviour: force.hold
			target: LocalTarget {
				targetObject: module
				targetProperty: 'encoderPressed'
			}
		}
	}

	ValueCCAssignment {
		objectName: 'Browse Encoder (Turn) ${module.name}'.trim()
		enabled: module.enabled
		channel: module.midiChannel
		cc: module.turnCC
		output: {
			if(module.enableBeatGridEditTurnAssignment && globalConfig.beatGridEditActive) {
				gridEditTurnOutputLoader.item
			}
			else {
				turnOutput
			}
		}
	}

	JogOutput {
		id: turnOutput
		type: 0
		roundRobin: false
		target: PropertyTarget {
			path: `/Qml/ControlFocus/${globalConfig.shift ? 'ShiftIndex' : 'Index'}`
		}
	}

	Loader {
		id: gridEditTurnOutputLoader
		sourceComponent: EncoderToActionOutput {
			targetLeft: PropertyTarget {
				path: globalConfig.activeGridEditDeckPath + (globalConfig.shift ? 'HalveTempo' : 'OffsetPhaseBackward')
			}
			targetRight: PropertyTarget {
				path: globalConfig.activeGridEditDeckPath + (globalConfig.shift ? 'DoubleTempo' : 'OffsetPhaseForward')
			}
		}
	}

	ValueNoteAssignment {
		objectName: 'Browse Encoder (Push) ${module.name}'.trim()
		channel: module.midiChannel
		note: module.pushNote
		output: actionLoader.item
	}

	Loader {
		id: actionLoader
		Component.onCompleted: {
			let actionName = ''
			let properties = {
				primaryTargetPropertyPath: Qt.binding(function() { return module.pushPropertyPath }),
			}

			if(module.hasInstantDouble) {
				actionName = 'ActionWithGridCueEdit'
				properties.doubleEnabled = Qt.binding(function() { return globalConfig.waveformIsForeground })
				properties.doubleAction =  deckAction.instantDouble
			}
			else {
				actionName = 'SingleAction'
			}

			setSource(`private/${actionName}.qml`, properties)
		}
	}

	Loader {
		active: ledType === LedType.Simple
		sourceComponent: OutputAssignment {
			objectName: 'Browse Encoder LED ${module.name}'.trim()
			properties: { 'ledValue': '' }
			enabled: module.enabled

			readonly property int ledValue: {
				if(module.encoderPressed) {
					127
				}
				else if(module.playerCueEditActive) {
					globalConfig.flashState ? 127 : 0
				}
				else if(module.playerGridEditActive) {
					deckConfig.tempoSyncedFlashState ? 127 : 0
				}
				else {
					1
				}
			}

			function send() {
				device.sendSimpleColor(globalConfig.midiChannel, module.pushNote, ledValue)
			}

			Component.onCompleted: send()
		}
	}
}

