import QtQuick 2.0
import airQuick 1.0
import StateMap 1.0
import EngineOS.UI.Style 1.0
import "../../../Items"

Item {
	id: savePreferencesEntry
	width: parent.width
	height: preferences.entryHeight

	DriveName {
		anchors {
			bottom: parent.bottom
			left: parent.left
			right: saveProfileButton.left
			topMargin: 85
		}
		height: 30
	}

	MouseArea {
		id: saveProfileButton
		z: 5
		anchors {
			topMargin: 62
			top: parent.top
			right: parent.right
		}

		width: 350
		height: 70

		onClicked: Planck.getProperty("/Client/Preferences/Profile/SaveApplicationProfile").translator.state = true
		visible: devicesConnected && isNotFolderDrive

		readonly property bool devicesConnected: Planck.librarianController.devicesController.deviceModelCountObserver.count > 0
		readonly property bool isNotFolderDrive: !Planck.librarianController.devicesController.isCurrentDeviceFolderDrive

		Rectangle {
			anchors.fill: parent
			color: parent.pressed ? Style.active01Color : Style.icon01Color
			radius: 5
			Behavior on color { ColorAnimation { duration: 150 } }
		}

		Text {
			anchors {
				verticalCenter: parent.verticalCenter
				verticalCenterOffset: 1
				right: parent.right
				rightMargin: 30
			}
			text: "SAVE TO MY DRIVE"
			font: preferences.inlineButtonFont.font
			color: Style.fontInverted02Color
			verticalAlignment: Text.AlignBottom
		}

		Image {
			anchors {
				verticalCenter: parent.verticalCenter
				left: parent.left
				leftMargin: 22
			}
			height: 30
			width: 42
			source: Qt.resolvedUrl("img/icon_JP07_export.png")
		}
	}
}

import QtQuick 2.12

import "../../../Entries/Base"

TwoStateTranslatorSwitchEntry {
	text: "Swap Main and Cue Output"
	prop: Planck.getProperty("/Client/SwapMainAndCueOutput")
}

import QtQuick 2.15
import Planck 1.0
import StateMap 1.0

Loader {
  active: root.useFakeAC ? root.fakeAC.hasBattery : Planck.powerStatusControl.hasBattery
  sourceComponent: Item {
    property var warningLevels: [10, 20]
    property int shutdownPercent: 1
    property int shutdownTimeMs: 3000

    property int previousPercent: -1

    readonly property real batteryPower: root.useFakeAC ? root.fakeAC.batteryPower : Planck.powerStatusControl.batteryPower
    readonly property int batteryPercent: Math.round(batteryPower * 100)
    onBatteryPercentChanged: {
      if(isOnAcPowerSource) {
        return
      }
      if(batteryPercent <= shutdownPercent) {
        if(!shutDownTimer.running) {
          shutDownTimer.start()
        }
      }
      else {
        if(shutDownTimer.running) {
          shutDownTimer.stop()
        }
      }

      for(let i in warningLevels) {
        let warningLevel = warningLevels[i]
        if(previousPercent > warningLevel && batteryPercent <= warningLevel) {
          showWarning()
        }
      }
      previousPercent = batteryPercent
    }

    readonly property bool isOnAcPowerSource: Planck.powerStatusControl.isOnAcPowerSource
    onIsOnAcPowerSourceChanged: {
      if(!isOnAcPowerSource) {
        if(batteryPercent <= Math.max.apply(Math, warningLevels)) {
          showWarning()
        }
      }
      else {
        shutDownTimer.stop()
        dismissWarning()
      }
    }

    function showWarning() {
      let messageObject = {
        id: "LowBatteryWarning",
        type: Prompt.Warning,
        title: "Battery level is low",
        message: `${Config.product.name} will shut down soon if not plugged in.`,
        options: Prompt.Ok
      }
      PlanckGUI.views.prompts.post(messageObject)
    }

    function dismissWarning() {
      PlanckGUI.views.prompts.drop("LowBatteryWarning")
    }

    Timer {
      id: shutDownTimer
      repeat: false
      interval: shutdownTimeMs
      running: false
      onTriggered: {
        Planck.writeToFile("/tmp/jp07-bypass-quit-filter", "")
        console.log("BATTERY INDICATED COMPLETE DRAIN; SHUT DOWN")
        Planck.getProperty("/Client/Quit").translator.state = true
      }
    }
  }
}

import QtQuick 2.12
import QtQuick.Controls 2.12
import QtQuick.Layouts 1.12

import EngineOS.UI.CompositeControls 1.0
import EngineOS.UI.Style 1.0

import Planck 1.0

import "../../../../../Skins/JP07/Views/MainView/Components" as Player

Control {
	id: control

	objectName: "DeckPerformanceData"

	Layout.fillWidth: true
	Layout.minimumHeight: 36
	Layout.maximumHeight: 36

	required property PerformanceViewDeckInterface deckView
	required property bool isPortrait

	Component {
		id: contentComp

		DeckPerformanceDataContent {
			deckView: control.deckView
		}
	}

	Component {
		id: portraitContentComp

		PortraitDeckPerformanceDataContent {
			deckView: control.deckView
		}
	}

	contentItem: Loader  {
		id: contentLoader
		visible: control.deckView.deckData.songLoaded
		sourceComponent: contentComp
	}

	background: Rectangle {
		color: Style.surface01Color
	}

	states: [
		State {
			name: "Portrait"
			when: control.visible
				  && control.isPortrait

			PropertyChanges {
				target: control
				Layout.minimumHeight: 128
				Layout.maximumHeight: 128
			}
			PropertyChanges {
				target: contentLoader
				sourceComponent: portraitContentComp
			}
		}
	]
}

